#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
P=Path('usmle/batch_specs_1401_1500/03_q1451_q1475_author_20260908_collision_repaired.json')

def ev(q,key,sid,loc,r):
 return [{'claim_id':f'Q{q}-{L}','option':L,'claim_locator':f'explanation.distractor_explanations.{L}','claim':r[L],'source_ids':[sid],'direct_or_inference':'direct' if L==key else 'inference','source_locator':loc,'item_specific_application':'Keyed target/mechanism is directly supported by the cited source; distractor rejection uses that mechanism plus stipulated experimental conditions.'} for L in 'ABCDE']
def qa(alt,res): return {'key_correctness':'PASS','all_options_review':'PASS','single_best_answer':'PASS','second_answer_attack':{'option':alt,'resolution':res,'status':'PASS'},'hidden_assumptions':'PASS','numerical_claims':'PASS — no invented dose, cutoff, response percentage, trial result, or empirical item statistic.','fabricated_distractors':'PASS','source_identity_setid_url_locator':'PASS','currentness':'PASS — current DailyMed SetID page reverified 2026-09-10; no unsupported revision date asserted.','blueprint':'PASS','difficulty':'Author estimate only','rationale':'PASS A-E','educational_objective':'PASS','adversarial_second_pass':'PASS','technical_hash_gate':'PENDING','unresolved_content_defects':[]}
def make(q,drug,system,disc,vig,lead,opts,key,construct,keyexp,rats,eo,title,setid,loc,alt,res):
 sid=f'Q{q}-LABEL'
 return {'num':q,'drug':drug,'country_scope':'United States','status':'AUTHOR_QA_PASS_PENDING_TECHNICAL_FREEZE_AND_INDEPENDENT_AUDIT','blueprint':{'primary_system':system,'primary_competency':'Medical Knowledge: Applying Foundational Science Concepts','disciplines':disc,'official_outline_path':[system],'specification_source_id':'USMLE-SPEC'},'item':{'vignette':vig,'lead_in':lead,'options':opts,'intended_key':key,'tested_construct':construct,'difficulty':'moderate-hard','difficulty_basis':'Author estimate based on mechanistic discrimination; no empirical calibration claimed.'},'explanation':{'key_explanation':keyexp,'distractor_explanations':rats,'educational_objective':eo},'sources':[{'source_id':sid,'title':title,'agency':'Manufacturer prescribing information hosted by NLM DailyMed','url':f'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid={setid}','setid':setid,'source_section_date':None,'date_basis':'Current DailyMed SetID page and cited mechanism section reverified 2026-09-10; no revision date inferred.','retrieved_at':'2026-09-10','section_locator':loc,'source_page_sha256':None,'cited_section_sha256':None,'hash_status':'PENDING_DETERMINISTIC_REFETCH_AND_HASH'}],'evidence_map':ev(q,key,sid,loc,rats),'author_qa':qa(alt,res)}
def main():
 b=json.loads(P.read_text()); xs={x['num']:x for x in b['items']}
 for q,d in {1454:'suzetrigine',1471:'evinacumab-dgnb',1472:'sotagliflozin',1473:'fitusiran'}.items(): assert xs[q]['drug']==d
 repl={}
 repl[1454]=make(1454,'efgartigimod alfa-fcab','Blood & Lymphoreticular/Immune Systems',['Pharmacology','Immunology'],'Endothelial cells expressing the neonatal Fc receptor are exposed to efgartigimod alfa-fcab. IgG recycling falls and extracellular IgG concentrations subsequently decline without inhibition of IgG synthesis by plasma cells.','Which direct action best explains this effect?',{'A':'Neutralization of interleukin-6','B':'Inhibition of complement C5','C':'Depletion of CD20-positive B cells','D':'Binding to the neonatal Fc receptor and reducing IgG recycling','E':'Inhibition of Bruton tyrosine kinase'},'D','FcRn binding with reduction of circulating IgG','Efgartigimod alfa-fcab is an IgG1-derived antibody fragment that binds the neonatal Fc receptor (FcRn), resulting in reduction of circulating IgG.',{'A':'IL-6 neutralization does not directly disrupt IgG salvage.','B':'C5 blockade acts on complement rather than FcRn-mediated IgG recycling.','C':'B-cell depletion can reduce antibody production over time but does not match preserved synthesis with impaired recycling.','D':'Correct. FcRn binding reduces IgG salvage/recycling and lowers circulating IgG.','E':'BTK inhibition alters B-cell signaling rather than directly blocking FcRn.'},'Connect FcRn blockade with accelerated loss of circulating IgG through reduced recycling.','VYVGART- efgartigimod alfa injection','8aefc8e3-26d6-4ff6-aab9-a7542927e084','12.1 Mechanism of Action','C','B-cell depletion can also lower autoantibodies, but the stem specifically preserves antibody synthesis and demonstrates loss of FcRn-dependent recycling.')
 repl[1471]=make(1471,'inclisiran','Cardiovascular System',['Pharmacology','Biochemistry'],'Hepatocytes take up a GalNAc-conjugated double-stranded RNA therapeutic. PCSK9 messenger RNA decreases, LDL-receptor surface expression rises, and the genomic PCSK9 sequence remains unchanged.','Which direct molecular process best explains these findings?',{'A':'RNA interference causing catalytic degradation of PCSK9 mRNA','B':'Monoclonal-antibody neutralization of circulating PCSK9','C':'CRISPR disruption of the PCSK9 gene','D':'Competitive inhibition of HMG-CoA reductase','E':'Activation of LDL-receptor transcription by a nuclear-receptor agonist'},'A','GalNAc-targeted siRNA degradation of PCSK9 mRNA','Inclisiran is a GalNAc-conjugated double-stranded siRNA taken up by hepatocytes, where RNA interference directs catalytic breakdown of PCSK9 mRNA, increasing LDL-receptor recycling and surface expression.',{'A':'Correct. Hepatocyte-targeted RNA interference directly degrades PCSK9 mRNA.','B':'An extracellular antibody would neutralize PCSK9 protein rather than catalytically lower its mRNA.','C':'The genomic sequence is unchanged, excluding gene editing.','D':'HMG-CoA reductase inhibition does not directly explain selective PCSK9-mRNA degradation.','E':'The defining event is RNA interference rather than nuclear-receptor-mediated transcriptional activation.'},'Differentiate hepatocyte-targeted siRNA-mediated PCSK9 mRNA degradation from protein neutralization and genome editing.','LEQVIO- inclisiran injection, solution','6fc0afca-4513-4c35-b594-6544aee29a44','12.1 Mechanism of Action','B','Both inclisiran and anti-PCSK9 antibodies increase LDL-receptor availability, but selective loss of PCSK9 mRNA identifies RNA interference.')
 repl[1472]=make(1472,'elafibranor','Gastrointestinal System',['Pharmacology','Biochemistry'],'A nuclear-receptor reporter assay is performed with elafibranor and its active metabolite. Activity is detected at several PPAR subtypes, while investigators avoid claiming that this in vitro profile fully explains the therapeutic effect in primary biliary cholangitis.','Which receptor profile is directly documented in vitro?',{'A':'Selective farnesoid X receptor agonism','B':'Agonism of PPAR-alpha, PPAR-gamma, and PPAR-delta','C':'Selective PPAR-gamma antagonism','D':'Pregnane X receptor inverse agonism','E':'Retinoid X receptor blockade'},'B','In-vitro activation of PPAR-alpha, PPAR-gamma, and PPAR-delta','Elafibranor and its main active metabolite GFT1007 are PPAR agonists that activate PPAR-alpha, PPAR-gamma, and PPAR-delta in vitro; labeling notes that the complete therapeutic mechanism in PBC is not well understood.',{'A':'FXR agonism is a distinct bile-acid pharmacology target.','B':'Correct. The label documents in-vitro activation of PPAR-alpha, PPAR-gamma, and PPAR-delta.','C':'The documented direction is agonism, not selective PPAR-gamma antagonism.','D':'PXR inverse agonism is not the reported receptor profile.','E':'RXR blockade does not match the labeled PPAR functional assays.'},'Separate a documented multi-PPAR in-vitro pharmacology profile from an incompletely understood disease-level therapeutic mechanism.','IQIRVO- elafibranor tablet, film coated','d78aa14f-6ec1-4b1d-a4ae-e48658137a25','12.1 Mechanism of Action','A','FXR is highly relevant to bile-acid physiology, but the cited functional assays directly identify PPAR-alpha, gamma, and delta activation.')
 repl[1473]=make(1473,'vorasidenib','Behavioral Health & Nervous Systems/Special Senses',['Pharmacology','Biochemistry'],'Glioma cells carrying an IDH1 R132 mutation are exposed to vorasidenib. Production of 2-hydroxyglutarate falls and differentiation markers partially recover. Parallel enzyme assays show inhibition of both IDH1 and IDH2 variants.','Which direct action best explains the metabolic change?',{'A':'Activation of wild-type IDH1 to increase alpha-ketoglutarate production','B':'Inhibition of mutant BRAF kinase','C':'Inhibition of IDH1 and IDH2 enzymes','D':'Blockade of glutaminase','E':'Inhibition of DNA methyltransferase 1'},'C','Dual IDH1/IDH2 inhibition with reduction of 2-hydroxyglutarate','Vorasidenib is a small-molecule inhibitor of IDH1 and IDH2. In IDH-mutant models it decreases production of the oncometabolite 2-hydroxyglutarate and can partially restore differentiation.',{'A':'Activating IDH1 would not explain direct inhibition in the enzyme assay.','B':'BRAF inhibition targets MAP-kinase signaling rather than mutant-IDH-derived 2-HG.','C':'Correct. Vorasidenib directly inhibits IDH1 and IDH2, reducing 2-HG production.','D':'Glutaminase inhibition affects glutamine metabolism but is not the documented direct target.','E':'DNMT1 inhibition changes DNA methylation downstream and does not directly inhibit mutant IDH enzymes.'},'Link inhibition of mutant IDH enzymes to reduced production of the oncometabolite 2-hydroxyglutarate.','VORANIGO- vorasidenib tablet, film coated','31405fee-55b7-4857-987e-2724ee76be84','12.1 Mechanism of Action','E','Epigenetic abnormalities are downstream of 2-HG, making DNMT-related mechanisms tempting, but the enzyme assay and fall in 2-HG directly identify IDH1/2 inhibition.')
 for q,v in repl.items(): xs[q].clear(); xs[q].update(v)
 assert ''.join(x['item']['intended_key'] for x in b['items'])==b['answer_key_sequence']
 b.setdefault('collision_repair',{}).setdefault('changes',[]).append('2026-09-10 aggregate repair: Q1454, Q1471, Q1472, Q1473 replaced with unique constructs after Q1301-Q1500 collision inventory.')
 P.write_text(json.dumps(b,indent=2,ensure_ascii=False)+'\n'); print(json.dumps({'replaced':sorted(repl),'status':'PASS'}))
if __name__=='__main__': main()
